2	
3	import java.time.Instant;
4	import java.time.LocalDate;
5	import java.time.ZoneOffset;
6	import java.util.Map;
7	
8	/**
9	 * 休药期纯计算工具（UTC 日界口径），无状态、可对任意输入复算。
10	 *
11	 * <p>口径（唯一）：</p>
12	 * <ul>
13	 *   <li>末次饲喂含药饲料时刻 {@code t}（UTC）所在 UTC 日历日 D；</li>
14	 *   <li>休药期届满日 = D + N 天（N = 各药物最大休药天数）；</li>
15	 *   <li>恰满休药天数当日 24:00（即届满日次日 00:00 UTC）之后方可出栏；</li>
16	 *   <li>判断出栏申请时刻 {@code a} 是否合法：{@code a >= earliestSlaughter}。</li>
17	 * </ul>
18	 */
19	public final class WithdrawalCalculator {
20	
21	    private WithdrawalCalculator() {
22	    }
23	
24	    /**
25	     * 取某时刻的 UTC 日历日。
26	     */
27	    public static LocalDate utcDate(Instant instant) {
28	        return instant.atZone(ZoneOffset.UTC).toLocalDate();
29	    }
30	
31	    /**
32	     * 计算休药期届满日（UTC）：末次饲喂日 + 休药天数。
33	     */
34	    public static LocalDate withdrawalUntilDate(Instant lastFeedAtUtc, int withdrawalDays) {
35	        if (withdrawalDays < 0) {
36	            throw new IllegalArgumentException("休药天数不能为负数");
37	        }
38	        return utcDate(lastFeedAtUtc).plusDays(withdrawalDays);
39	    }
40	
41	    /**
42	     * 最早合法出栏时刻：届满日次日 00:00 UTC（即届满日当日 24:00）。
43	     */
44	    public static Instant earliestSlaughter(LocalDate withdrawalUntilDate) {
45	        return withdrawalUntilDate.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();
46	    }
47	
48	    /**
49	     * 合并多个含药配方/饲喂事件：取最晚末次饲喂时刻与各药物最大休药天数。
50	     *
51	     * @param contributions 每项为 {lastFeedAtUtc: Instant, maxWithdrawalDays: int}
52	     * @return 合并后的最晚饲喂时刻、决定性最大休药天数及对应届满日；无贡献项返回 null
53	     */
54	    @SafeVarargs
55	    public static MergedWithdrawal merge(Map.Entry<Instant, Integer>... contributions) {
56	        Instant latestFeed = null;
57	        int maxDays = 0;
58	        for (Map.Entry<Instant, Integer> e : contributions) {
59	            if (e.getKey() == null) {
60	                continue;
61	            }
62	            if (latestFeed == null || e.getKey().isAfter(latestFeed)) {
63	                latestFeed = e.getKey();
64	            }
65	            maxDays = Math.max(maxDays, e.getValue());
66	        }
67	        if (latestFeed == null) {
68	            return null;
69	        }
70	        LocalDate until = withdrawalUntilDate(latestFeed, maxDays);
71	        return new MergedWithdrawal(latestFeed, maxDays, until, earliestSlaughter(until));
72	    }
73	
74	    /**
75	     * 合并结果。
76	     *
77	     * @param latestFeedAtUtc       最晚末次含药饲喂时刻
78	     * @param maxWithdrawalDays     各药物最大休药天数
79	     * @param withdrawalUntilDate   休药期届满日（UTC 日历日）
80	     * @param earliestSlaughterUtc  最早合法出栏时刻（UTC）
81	     */
82	    public record MergedWithdrawal(
83	            Instant latestFeedAtUtc,
84	            int maxWithdrawalDays,
85	            LocalDate withdrawalUntilDate,
86	            Instant earliestSlaughterUtc
87	    ) {
88	    }
89	}
