29	    public DictRepository(JdbcTemplate jdbc) {
30	        this.jdbc = jdbc;
31	    }
32	
33	    /** 药物字典行。 */
34	    public record DrugDict(String code, String name, BigDecimal maxRatio, int withdrawalDays, boolean active) {
35	    }
36	
37	    public Optional<DrugDict> findDrug(String code) {
38	        List<DrugDict> list = jdbc.query(
39	                "SELECT code, name, max_ratio, withdrawal_days, active FROM drug_additive WHERE code = ?",
40	                DRUG_MAPPER, code);
41	        return list.stream().findFirst();
42	    }
43	
44	    public List<DrugDict> findDrugs(List<String> codes) {
45	        if (codes.isEmpty()) {
46	            return List.of();
47	        }
48	        String placeholders = String.join(",", codes.stream().map(c -> "?").toList());
49	        return jdbc.query(
50	                "SELECT code, name, max_ratio, withdrawal_days, active FROM drug_additive WHERE code IN ("
51	                        + placeholders + ")",
52	                DRUG_MAPPER, codes.toArray());
53	    }
54	
55	    public List<String> findAllowedSpecies(String drugCode) {
56	        return jdbc.queryForList(
57	                "SELECT species FROM drug_allowed_species WHERE drug_code = ?",
58	                String.class, drugCode);
59	    }
60	
61	    /**
62	     * 统计给定药物集合命中的配伍禁忌对数（禁忌表按编码字典序存无序对）。
63	     */
64	    public long countContraindicationPairs(List<String> drugCodes) {
65	        if (drugCodes.size() < 2) {
66	            return 0;
67	        }
68	        String placeholders = String.join(",", drugCodes.stream().map(c -> "?").toList());
69	        Long count = jdbc.queryForObject(
70	                "SELECT COUNT(*) FROM contraindication "
71	                        + "WHERE drug_a_code IN (" + placeholders + ") "
72	                        + "AND drug_b_code IN (" + placeholders + ")",
73	                Long.class, concatArgs(drugCodes));
74	        return count == null ? 0 : count;
75	    }
76	
77	    public long countIngredients(List<String> codes) {
78	        if (codes.isEmpty()) {
79	            return 0;
80	        }
81	        String placeholders = String.join(",", codes.stream().map(c -> "?").toList());
82	        Long count = jdbc.queryForObject(
83	                "SELECT COUNT(*) FROM ingredient WHERE code IN (" + placeholders + ")",
84	                Long.class, codes.toArray());
85	        return count == null ? 0 : count;
86	    }
87	
88	    private Object[] concatArgs(List<String> codes) {
89	        Object[] args = new Object[codes.size() * 2];
90	        for (int i = 0; i < codes.size(); i++) {
91	            args[i] = codes.get(i);
92	            args[i + codes.size()] = codes.get(i);
93	        }
94	        return args;
