private IdempotencyService.Outcome doReportTreatment(TreatmentReportRequest request) {
    BatchRepository.BatchRow batch = batchRepository.lockAndGet(request.batchNo());

    // 双人确认：恰好两名不同养殖端人员，单人直报不生效。
    List<String> confirmers = request.confirmedBy() == null ? List.of() : request.confirmedBy();
    long distinct = confirmers.stream().filter(c -> c != null && !c.isBlank()).distinct().count();
    if (confirmers.size() != 2 || distinct != 2) {
        return new IdempotencyService.Outcome(rejectedResponse(request, "治疗直报须两名不同养殖端人员确认，单人直报不生效"), 422);
    }

    // 兽药目录外拒绝受理，不改变原出栏日。
    Optional<DictRepository.VetDrugDict> drugOpt = dictRepository.findVetDrugByName(request.drugName());
    if (drugOpt.isEmpty()) {
        return new IdempotencyService.Outcome(rejectedResponse(request, "兽药目录外药品，拒绝受理: " + request.drugName()), 422);
    }
    DictRepository.VetDrugDict drug = drugOpt.get();

    Instant now = clock.instant();
    boolean slaughtered = BatchStatus.SLAUGHTERED.name().equals(batch.status());
    // 出栏核销终态（计划出栏时刻已过）后迟到的直报：只记事件并告警。
    boolean late = slaughtered && batch.slaughteredAtUtc() != null && !batch.slaughteredAtUtc().isAfter(now);

    long reportId;
    try {
        reportId = treatmentReportRepository.insert(...);
    } catch (DuplicateKeyException e) {
        throw ApiException.conflict("同一批次同一给药时刻已存在进行中直报: " + request.batchNo() + " " + request.administeredAtUtc());
    }

    if (late) {
        alertRepository.insert(AlertType.LATE_TREATMENT_REPORT.name(), batch.batchNo(), null, "...");
        return new IdempotencyService.Outcome(response with current batch fields, late=true, alerted=true, revoked empty), 200);
    }

    // 重算合并休药期（含本次直报）。
    Merged merged = recomputeBatchWithdrawal(batch.id());
    batchRepository.updateWithdrawal(batch.id(), merged==null?null:merged.latestFeed(), ...);
    Instant newEarliest = merged == null ? null : WithdrawalCalculator.earliestSlaughter(merged.untilDate());

    List<String> revoked = new ArrayList<>();
    if (slaughtered) {
        // 已批准但计划出栏时刻尚在未来：与新最早出栏日冲突的申请同事务撤销。
        List<ApplicationRow> approved = slaughterApplicationRepository.findApprovedByBatch(batch.id());
        boolean anyRevoked = false;
        for (ApplicationRow app : approved) {
            if (newEarliest != null && app.applyAtUtc().isBefore(newEarliest)) {
