                slaughterApplicationRepository.insertRevocation(app.id(), app.requestId(), batch.id(), batch.batchNo(), app.applyAtUtc(), newEarliest, reportId, "...");
                revoked.add(app.requestId());
                anyRevoked = true;
            }
        }
        if (anyRevoked) {
            batchRepository.clearSlaughter(batch.id());
        }
    }

    TreatmentReportResponse response = new TreatmentReportResponse(...);
    return new IdempotencyService.Outcome(response, 200);
}
