        postJson("/api/slaughter-applications", Map.of(
                "requestId", "REQ-TR3-SL",
                "batchNo", "B-TR3",
                "applyAtUtc", scheduledAt.toString()));

        // 头孢噻呋仅 4 天：新最早出栏日仍早于已批准时刻，不冲突、不撤销。
        MvcResult result = postJson("/api/treatment-reports",
